import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {loadPlaywright, launchBrowser, ensureServer, boot, gotoRoute, reloadApp, contextOptions} from './lib.mjs';

// These descriptors were generated by the actual 8517db3 player in a separate
// Git archive. Current historical reconstruction is not the fixture oracle.
const fixture=JSON.parse(fs.readFileSync(new URL('./fixtures/formal-ci-agreement-legacy.json',import.meta.url)));
const entries=[...new Set(fixture.records.map(r=>r.entryId))];
const targets=entryId=>fixture.records.filter(r=>r.entryId===entryId&&!r.ordinary&&r.variant===0&&r.format==='type'&&r.chapterId!=='present');
const hash=value=>createHash('sha256').update(value).digest('hex');
for(const r of fixture.records)assert.equal(hash(JSON.stringify(r.descriptor)),r.sha256);
const {chromium,webkit,devices}=await loadPlaywright(), stop=await ensureServer();
const engine=process.env.COURSE_BROWSER==='webkit'?'webkit':'chromium';
const browser=engine==='webkit'?await webkit.launch():await launchBrowser(chromium);
const context=await browser.newContext(contextOptions(devices['iPhone 13'],{viewport:{width:375,height:667},reducedMotion:'reduce'}));
await context.addInitScript(()=>{
  window.__formalSpeech=[];
  Object.defineProperty(window,'SpeechSynthesisUtterance',{configurable:true,value:class {constructor(text){this.text=text;}}});
  Object.defineProperty(window,'speechSynthesis',{configurable:true,value:{getVoices:()=>[],cancel(){},speak(u){window.__formalSpeech.push({text:u.text,lang:u.lang});}}});
});
const page=await context.newPage(), results=[], errors=[];
const counts={currentTyped:0,currentPairs:0,wrongGenderRejected:0,priorForms:0,priorPairs:0,validPrior:0,unknownRevision:0};
page.setDefaultTimeout(15000);page.on('pageerror',e=>errors.push(e.message));
const check=async(name,run)=>{await run();results.push(name);console.log('PASS',name);};
const saved=()=>page.evaluate(async()=>{const {store}=await import('./js/store.js');return {session:store.learning.session,events:structuredClone(store.learning.events),completions:structuredClone(store.learning.completions),xp:store.current.stats.xp};});
const route=source=>`/learn/verb/${encodeURIComponent(source.entryId)}?session=${encodeURIComponent(source.id)}`;
const noCredit=(after,before)=>{assert.deepEqual(after.events,before.events);assert.deepEqual(after.completions,before.completions);assert.equal(after.xp,before.xp);};
async function seed({entryId,targetId,chapterId,variant=0,format='type',old=null,answered=false,unknown=false}={}){
  await gotoRoute(page,'/home');
  return page.evaluate(async opt=>{
    const {store}=await import('./js/store.js'),{getEntry}=await import('./js/data.js');
    const {buildLesson}=await import('./js/learning/lesson-content.js');
    const {buildJourneyQuestion}=await import('./js/learning/lesson-questions.js');
    const {createJourneySession,pinJourneyScene,currentJourneyStep}=await import('./js/learning/journey.js');
    store.setSetting('tts',false);store.setSetting('adaptiveLearning',true);
    const entry=getEntry(opt.entryId),plan=buildLesson(entry,{questionBuilder:buildJourneyQuestion});
    const chapters=opt.old?(opt.old.ordinary?plan.questionHistory.ordinaryChapters:plan.questionHistory.chapters):plan.chapters;
    const chapter=chapters.find(c=>c.id===opt.chapterId),target=chapter.groups.flatMap(g=>g.targets).find(t=>t.id===opt.targetId);
    const session=createJourneySession({id:'formal-browser-'+crypto.randomUUID(),plan,chapterId:chapter.id,caseMode:true});
    const phase=opt.format==='pairs'?'guided':'independent';
    Object.assign(session.journey,{chapterId:chapter.id,phase:phase==='guided'?'guided':'practice',groupIndex:chapter.groups.findIndex(g=>g.targets.includes(target)),serial:1,
      queue:chapter.groups.flatMap(g=>g.targets).filter(t=>t.id!==target.id).map(t=>t.id),current:{targetId:target.id,phase,format:opt.format,variant:opt.variant,
        questionId:session.id+':journey:1',supplemental:false,repairTag:null,
        ...opt.old?.ordinary?{}:{scenePolicy:'expanded-v1'},questionRevision:opt.old?plan.questionHistory.previousRevision:plan.questionHistory.currentRevision}});
    if(opt.old?.ordinary)delete session.journey.verbFlowVersion;
    session.journey.variants[target.id]={guided:phase==='guided'?opt.variant:0,independent:phase==='independent'?opt.variant+1:0,repair:0};
    session.ui={version:2,questionId:session.journey.current.questionId,draft:'  exact saved formal draft  ',given:opt.answered?'Original submitted form':'',
      result:opt.answered?{ok:false,outcome:'incorrect',feedback:'Exact earlier formal feedback',components:[],errorTags:['agreement']}:null,
      assistance:[],exposures:{},history:[],historyCursor:null,overview:false,
      // Canonical empty presentation fields avoid confusing harmless default
      // initialization with a change to the old draft/result/history receipt.
      caseDrafts:{},formDecks:{},historyReturnScroll:0,mapOpen:false,paused:false,visits:{}};
    if(opt.answered){
      const event={id:session.journey.current.questionId,sessionId:session.id,index:0,at:Date.now()-1000,objectiveId:target.id,targetId:target.id,entryId:entry.id,
        kind:'verb',skill:target.skill,tense:target.tense,person:target.person,role:target.role,policy:'journey-v1',contentVersion:plan.version,chapterId:chapter.id,
        mode:'production',activityKind:'independent',firstAttempt:true,ok:false,outcome:'incorrect',errorTags:['agreement'],assistance:[],variantId:target.id+':old-form',contextId:target.id+':old-form',xp:0,countStats:false};
      store.recordLearningAttempt(event);session.index=1;session.answeredEventIds=[event.id];session.journey.awaitingContinue=true;
      session.journey.lastAttempt={id:event.id,targetId:target.id,variant:opt.variant,ok:false,outcome:'incorrect',errorTags:['agreement']};
    }
    if(opt.old)session.journey.current.formSnapshot={version:1,entryId:entry.id,targetId:target.id,chapterId:chapter.id,sourceRevision:plan.questionHistory.previousRevision,
      scenePolicy:opt.old.ordinary?null:'expanded-v1',variant:opt.variant,format:opt.format,phase,repairTag:null,descriptor:opt.old.descriptor};
    let current=pinJourneyScene(plan,session);
    if(opt.unknown){current.journey.current.formSnapshot.sourceRevision='future-formal-source-v999';current.journey.current.questionRevision='future-formal-source-v999';}
    store.saveLearningSession(current);await store.saveNow();
    const step=currentJourneyStep(plan,current),q=step.type==='question'?buildJourneyQuestion(entry,step.chapter,step.target,{...step,questionHistory:plan.questionHistory}):null;
    return {id:current.id,entryId:entry.id,questionId:current.journey.current.questionId,revision:plan.questionHistory.currentRevision,form:current.journey.current.formSnapshot,q};
  },{entryId,targetId,chapterId,variant,format,old,answered,unknown});
}
async function typed(source,{reject=false}={}){
  await gotoRoute(page,route(source));await page.locator('[data-answer]').waitFor();
  const female=source.form.variant%2===0,answer=source.q.answer[0];
  assert.match(await page.locator('.journey-prompt').textContent(),female?/Signora Rossi/:/Signor Rossi/);
  assert(source.q.answer.every(a=>a.endsWith(female?'a':'o')));
  await page.evaluate(()=>window.__formalSpeech=[]);await page.locator('[data-answer-audio]').click();
  assert.deepEqual(await page.evaluate(()=>window.__formalSpeech),[{text:source.q.say,lang:'it-IT'}]);
  assert(source.q.say.endsWith(female?'a':'o'));
  await page.locator('[data-answer]').fill(reject?answer.slice(0,-1)+(female?'o':'a'):answer);
  await page.locator('[data-check]').click();await page.locator('[data-continue]').waitFor();
  const answered=await saved();assert.equal(answered.session.ui.result.ok,!reject);assert.equal(answered.session.journey.current.questionId,source.questionId);
  if(reject)counts.wrongGenderRejected++;else counts.currentTyped++;
  return answered;
}
async function corrected(source,before,{reload=true}={}){
  await gotoRoute(page,route(source));await page.getByText('This example has been corrected',{exact:true}).waitFor();
  assert.equal(await page.locator('[data-answer], [data-check], [data-choice], [data-pair-left], [data-pair-right], [data-answer-audio]').count(),0);
  let pending=await saved();noCredit(pending,before);assert.deepEqual(pending.session.journey.current,before.session.journey.current);
  assert.equal(pending.session.ui.draft,before.session.ui.draft);assert.deepEqual(pending.session.ui.result,before.session.ui.result);
  if(reload){await reloadApp(page);await page.getByText('This example has been corrected',{exact:true}).waitFor();pending=await saved();noCredit(pending,before);assert.deepEqual(pending.session.journey.current,before.session.journey.current);assert.equal(pending.session.ui.draft,before.session.ui.draft);assert.deepEqual(pending.session.ui.result,before.session.ui.result);}
  // Even a scripted obsolete grading click cannot mint credit while corrected.
  await page.evaluate(()=>{const b=document.createElement('button');b.dataset.check='';document.querySelector('#view').append(b);b.click();b.remove();});
  noCredit(await saved(),before);
  await page.locator('[data-continue]').click();await page.locator('.journey-prompt').waitFor();
  const after=await saved(),recovery=after.session.sceneCorrectionRecovery.at(-1);
  noCredit(after,before);assert.notEqual(after.session.journey.current.questionId,source.questionId);assert.equal(after.session.journey.current.formSnapshot.sourceRevision,source.revision);
  assert.equal(after.session.index,before.session.index);assert.deepEqual(after.session.answeredEventIds,before.session.answeredEventIds);
  assert.deepEqual(recovery.current,before.session.journey.current);assert.deepEqual(recovery.journey,before.session.journey);assert.deepEqual(recovery.ui,before.session.ui);
  if(reload){await reloadApp(page);await page.locator('.journey-prompt').waitFor();const resumed=await saved();assert.equal(resumed.session.journey.current.questionId,after.session.journey.current.questionId);assert.deepEqual(resumed.session.sceneCorrectionRecovery,after.session.sceneCorrectionRecovery);noCredit(resumed,before);}
}
try{
  await boot(page);
  for(const entryId of entries){
    await check(entryId+' · all seven current compounds accept and speak only the requested named gender',async()=>{
      for(const r of targets(entryId))for(const variant of [0,1])await typed(await seed({...r,variant}));
    });
    await check(entryId+' · opposite-gender past form is rejected by the actual controller',async()=>{
      const r=targets(entryId).find(r=>r.chapterId==='past');for(const variant of [0,1])await typed(await seed({...r,variant}),{reject:true});
    });
    await check(entryId+' · current woman/man paired labels accept and speak the matching formal tile',async()=>{
      for(const variant of [0,1]){
        const old=fixture.records.find(r=>r.entryId===entryId&&r.format==='pairs'&&!r.ordinary),source=await seed({...old,old:null,variant});
        await gotoRoute(page,route(source));await page.locator('[data-pair-left]').first().waitFor();
        const formal=source.q.pairs.find(p=>p.targetId.endsWith('::formal'));assert(formal);
        const left=page.locator('[data-pair-left]').filter({hasText:formal.label});assert.equal(await left.count(),1);assert.match(formal.label,variant?/\(man\)/:/\(woman\)/);
        assert(formal.answers.every(a=>a.endsWith(variant?'o':'a')));assert(formal.canonical.endsWith(variant?'o':'a'));
        await page.evaluate(async()=>{window.__formalSpeech=[];(await import('./js/store.js')).store.setSetting('tts',true);});await left.click();
        const right=page.locator('[data-pair-right]').filter({hasText:formal.canonical});await right.first().click();
        await page.waitForFunction(()=>import('./js/store.js').then(({store})=>store.learning.session.ui.activity?.feedback?.correct===true));
        assert.equal((await saved()).session.ui.activity.feedback.expected,formal.canonical);
        assert((await page.evaluate(()=>window.__formalSpeech)).some(u=>u.text===formal.canonical||u.text==='Lei '+formal.canonical));counts.currentPairs++;
      }
    });
    await check(entryId+' · every invalid prior compound preserves exact saved receipt until explicit Continue',async()=>{
      for(const [index,r]of targets(entryId).entries()){
        const ordinary=index%2===1,variant=index%2,old=fixture.records.find(f=>f.entryId===entryId&&f.targetId===r.targetId&&f.format==='type'&&f.ordinary===ordinary&&f.variant===variant);
        const source=await seed({...old,old,answered:index%2===0}),before=await saved();await corrected(source,before,{reload:index===0});counts.priorForms++;
      }
    });
    await check(entryId+' · both old matching policies stop before grading and retain the old board',async()=>{
      for(const old of fixture.records.filter(r=>r.entryId===entryId&&r.format==='pairs')){const source=await seed({...old,old}),before=await saved();await corrected(source,before);counts.priorPairs++;}
    });
    await check(entryId+' · valid old present draft, answer, feedback and Back page remain exact',async()=>{
      const old=fixture.records.find(r=>r.entryId===entryId&&r.chapterId==='present'&&!r.ordinary&&r.variant===0),source=await seed({...old,old});
      await gotoRoute(page,route(source));await page.locator('[data-answer]').waitFor();assert.equal(await page.locator('[data-answer]').inputValue(),'  exact saved formal draft  ');
      assert.deepEqual((await saved()).session.journey.current.formSnapshot,source.form);
      await page.locator('[data-answer]').fill(old.descriptor.answer[0]);await page.locator('[data-check]').click();await page.locator('[data-continue]').waitFor();const answered=await saved();assert.equal(answered.session.ui.result.ok,true);
      await reloadApp(page);await page.locator('[data-continue]').waitFor();assert.deepEqual((await saved()).session.ui.result,answered.session.ui.result);
      await page.locator('[data-continue]').click();await page.locator('.journey-prompt').waitFor();await page.locator('[data-lesson-back]').click();await page.locator('.journey-history-banner').waitFor();
      assert.match(await page.locator('.journey-prompt').textContent(),/Signora Rossi/);assert.equal((await saved()).session.ui.history.at(-1).formSnapshot.sourceRevision,source.form.sourceRevision);
      await reloadApp(page);await page.locator('.journey-history-banner').waitFor();noCredit(await saved(),answered);counts.validPrior++;
    });
  }
  await check('Formal agreement stays exact under permissive/strict accent policies and preserves the original spelling',async()=>{
    const r=targets('v:restarci').find(r=>r.chapterId==='past');
    for(const strict of [false,true]){
      const source=await seed({...r,variant:0});await page.evaluate(async strict=>(await import('./js/store.js')).store.setSetting('accentStrict',strict),strict);
      await gotoRoute(page,route(source));await page.locator('[data-answer]').waitFor();assert(source.q.answer.includes("c'è restata"));
      await page.locator('[data-answer]').fill("c'e restata");await page.locator('[data-check]').click();await page.locator('[data-continue]').waitFor();
      const after=await saved();assert.equal(after.session.ui.result.ok,!strict);assert.equal(after.session.ui.result.submission.originalText,"c'e restata");
      assert.equal(await page.locator('[data-answer]').inputValue(),strict?"c'e restata":"c'è restata");
      if(!strict){await page.locator('.submission-note summary').click();assert.match(await page.locator('.submission-note').textContent(),/As typed: c'e restata/);}
      await reloadApp(page);await page.locator('[data-continue]').waitFor();assert.deepEqual((await saved()).session.ui.result,after.session.ui.result);noCredit(await saved(),after);
    }
    const source=await seed({...r,variant:0});await page.evaluate(async()=>(await import('./js/store.js')).store.setSetting('accentStrict',false));
    await gotoRoute(page,route(source));await page.locator('[data-answer]').waitFor();await page.locator('[data-answer]').fill("c'è restato");await page.locator('[data-check]').click();await page.locator('[data-continue]').waitFor();
    const wrong=await saved();assert.equal(wrong.session.ui.result.ok,false);assert(wrong.session.ui.result.errorTags.includes('agreement'));assert.match(await page.locator('.journey-feedback').textContent(),/With essere, match the participle to the subject: masculine\/feminine/);
    counts.wrongGenderRejected++;
  });
  await check('Unknown source revision is unavailable, keeps draft/answered receipt and reloads exactly',async()=>{
    for(const answered of [false,true]){
      const old=fixture.records.find(r=>r.entryId===entries[0]&&r.chapterId==='present'&&!r.ordinary&&r.variant===0),source=await seed({...old,old,answered,unknown:true}),before=await saved();
      await gotoRoute(page,route(source));await page.getByText('This saved lesson cannot open yet',{exact:true}).waitFor();
      assert.equal(await page.locator('[data-answer], [data-check], [data-continue], [data-pair-left], [data-answer-audio]').count(),0);
      await reloadApp(page);await page.getByText('This saved lesson cannot open yet',{exact:true}).waitFor();const after=await saved();noCredit(after,before);
      assert.deepEqual(after.session.journey.current,before.session.journey.current);assert.equal(after.session.ui.draft,before.session.ui.draft);assert.deepEqual(after.session.ui.result,before.session.ui.result);assert.deepEqual(after.session.answeredEventIds,before.session.answeredEventIds);counts.unknownRevision++;
    }
  });
  assert.deepEqual(errors,[]);
  const sources=['js/learning/lesson-content.js','js/learning/lesson-questions.js','js/learning/journey-form.js','js/learning/journey.js','js/views/learnJourney.js','js/learning/verb-question-history-data.js'];
  const report={date:'2026-10-04',engine,status:'passed',checks:results.length,results,counts,baseline:fixture.baseline,fixtureDescriptors:fixture.records.length,
    sourceSHA256:Object.fromEntries(sources.map(p=>[p,hash(fs.readFileSync(new URL('../'+p,import.meta.url)))])),fixtureSHA256:hash(fs.readFileSync(new URL('./fixtures/formal-ci-agreement-legacy.json',import.meta.url))),testSHA256:hash(fs.readFileSync(new URL('./formal-ci-agreement-e2e.mjs',import.meta.url))),errors,
    scope:'Real routes/controller/local persistence with synthetic learners and captured speech requests. All 35 affected compound targets; bounded paired/present/history checks. No synthesized audio-quality, native-human or release claim.'};
  fs.writeFileSync(new URL(`../docs/implementation/programme/formal-ci-agreement-${engine}.json`,import.meta.url),JSON.stringify(report,null,2)+'\n');
  console.log(results.length+' '+engine+' formal agreement browser checks passed. '+JSON.stringify(counts));
}finally{await context.close();await browser.close();stop();}
